def mk(s,forms,reviews,prior,deck,lo,hi,theme):
 paras=list(s['paras']);paras[1]+=' '+' '.join(USE[f] for f in forms);paras[2]+=' '+review_bridge(reviews);paras,text=fit(paras,lo,hi);P=base.prior(prior);new=[base.nt(f,text,deck) for f in forms];rev=[base.rev(f,P) for f in reviews];ids={t['form']:t['id'] for t in new+rev};q,a=base.qa(qa_items(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C1','unit':6,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':'instructional','genre':s['genre'],'domains':s['domains'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'new','description':'scope deontic and evidential claims; distinguish allegation, fact, qualification and remedy'}],'discourse_targets':[{'id':s['id']+'-d1','role':'new','description':'reconstruct rule, fact pattern, competing interpretation, proportionality and revision condition'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C1 Unit06 jurisdiction-neutral legal interpretation.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Fictional/jurisdiction-neutral legal reasoning against exact Unit05 lock.']},'paired_text_group':s.get('pair'),'prerequisites':['French C1 Unit05'],'difficulty_notes_internal':'C1 legal interpretation without jurisdiction-specific legal claims.','reader_tags':['unit_role:instructional','generation_batch','french_c1_u06']}
def specs():
 return [
 {'id':'fr-c1-u06-p01','seq':31,'title':'Une règle claire peut produire un cas difficile','genre':'case-style explanation','domains':['public','professional'],'topics':['procedure','institutional authority'],'paras':["Dans un dossier fictif, une administration doit décider si une demande tardive peut néanmoins être examinée. Le texte de la règle fixe un délai, mais une autre disposition exige que l’institution fournisse une information accessible sur la procédure. La personne affirme que l’avis reçu indiquait une date différente. Le problème n’est donc pas de choisir entre obéir ou désobéir à la règle : il faut déterminer quelle obligation institutionnelle est pertinente pour appliquer le délai.","L’analyse reconstruit d’abord la chronologie et sépare les actes de chaque participant. Elle demande qui a envoyé l’avis, quelle version était accessible, quand la personne a tenté d’agir et quelle autorité possédait la personne qui a répondu. Une institution ne peut pas corriger l’incertitude en supposant que son propre dossier est nécessairement complet.","L’objection la plus forte affirme qu’accepter toute erreur alléguée rendrait les délais inutiles. Le dossier accepte cette préoccupation et exige donc une preuve indépendante ou une trace vérifiable de l’information contradictoire. L’exception n’est pas fondée sur la seule affirmation du demandeur, mais sur une incohérence que l’institution peut elle-même examiner.","La recommandation est étroite : lorsque l’institution a fourni une information matériellement incompatible avec son propre délai et que la personne a raisonnablement agi sur cette information, une procédure de correction doit être disponible. Le texte ne prétend pas que tout retard soit excusable; il identifie une condition précise qui modifie l’équité de l’application."],'qclaim':'Quel est le conflit interprétatif principal ?','aclaim':'Il faut concilier le délai avec l’obligation de fournir une information procédurale fiable lorsqu’une erreur institutionnelle est documentée.','qinfer':'Que refuse le texte à propos du dossier administratif ?','ainfer':'Il refuse de supposer que le dossier institutionnel est complet simplement parce qu’il est officiel.','qassume':'Quelle condition rend l’exception contrôlable ?','aassume':'Une trace indépendante doit montrer que l’information contradictoire a réellement été fournie.','qrelation':'Comment le texte répond-il à l’objection sur l’affaiblissement des délais ?','arelation':'Il limite la correction aux erreurs institutionnelles vérifiables plutôt qu’à toute affirmation tardive.','astance':'Interpréter la procédure de façon cohérente avec la fiabilité de l’information et une exception étroite et vérifiable.','asummary':'Le délai reste la règle, mais une erreur institutionnelle documentée peut justifier une voie de correction limitée.'},
 {'id':'fr-c1-u06-p02','seq':32,'title':'Accusation, témoignage et qualification ne sont pas la même chose','genre':'commentary','domains':['public','educational'],'topics':['evidence','criminal labels'],'paras':["Un second cas fictif examine la manière dont un récit public transforme progressivement un soupçon en conclusion. Un objet disparaît, un témoin situe une personne près du lieu, puis un commentaire affirme que cette personne a commis un acte grave. Chaque phrase ajoute pourtant un niveau d’interprétation différent : présence, action, intention et qualification ne sont pas interchangeables.","Le commentaire reconstruit les propositions une par une. Il compare ce que le témoin dit avoir vu, ce qu’une caméra montre réellement et ce que l’accusation suppose sur l’intention. Même un témoignage sincère peut être incomplet; une image peut établir un déplacement sans expliquer sa raison.","L’objection affirme qu’une accumulation d’indices peut raisonnablement soutenir une conclusion même sans observation directe. Le texte l’accepte, mais demande une chaîne explicite : chaque indice doit augmenter la plausibilité de l’hypothèse pertinente plutôt que simplement répéter la même présomption sous une autre forme. Une étiquette grave ne doit apparaître qu’après cette reconstruction.","La conclusion distingue enfin responsabilité procédurale et certitude morale. Le dossier peut justifier une enquête supplémentaire, une mesure conservatoire ou une décision finale à des seuils différents. Plus la conséquence est difficile à corriger, plus l’argument doit préciser les alternatives encore compatibles avec les faits."],'qclaim':'Quelle distinction centrale structure le passage ?','aclaim':'Présence, action, intention et qualification juridique sont des étapes différentes qui doivent être justifiées séparément.','qinfer':'Pourquoi un témoignage sincère peut-il être insuffisant ?','ainfer':'Parce que la sincérité ne garantit ni l’exhaustivité de l’observation ni la justesse de l’interprétation.','qassume':'Que suppose une accumulation d’indices convaincante ?','aassume':'Que les indices apportent des raisons relativement distinctes et pertinentes plutôt que de répéter la même présomption.','qrelation':'Comment le texte traite-t-il l’idée qu’une preuve directe est toujours nécessaire ?','arelation':'Il admet une conclusion par indices, mais exige que la chaîne inférentielle soit explicite et testable.','astance':'Employer les qualifications graves seulement après avoir séparé et justifié les étapes factuelles et inférentielles.','asummary':'Le passage demande une chaîne de preuve explicite entre observation, intention attribuée, qualification et niveau de conséquence.'},
 {'id':'fr-c1-u06-p03','seq':33,'title':'Point de vue A : la liberté exige une justification qui se renouvelle','genre':'argument','domains':['public','educational'],'topics':['liberty','detention','remedy'],'pair':PAIR,'paras':["Le premier point de vue part d’un principe institutionnel : une restriction grave de liberté ne devrait pas se maintenir uniquement parce qu’elle a été autorisée une première fois. Les circonstances changent, les preuves peuvent s’affaiblir ou des alternatives moins intrusives peuvent devenir disponibles. La justification doit donc être réexaminée à intervalles définis.","Cette position ne nie pas qu’une restriction temporaire puisse protéger une enquête ou prévenir un risque concret. Elle affirme plutôt que la durée fait partie du problème. Une raison suffisante pour quelques heures ou quelques jours ne justifie pas automatiquement une conséquence beaucoup plus longue.","Le contreargument invoque le coût de réexamens fréquents et le risque de décisions incohérentes. Le point de vue A répond qu’un mécanisme de révision peut être standardisé : l’institution annonce les facteurs à réévaluer, les nouvelles informations pertinentes et les alternatives disponibles. La révision devient une discipline plutôt qu’une improvisation.","La conclusion donne la priorité à la réversibilité. Lorsqu’une erreur prive une personne de liberté, le dommage se poursuit tant que la décision n’est pas corrigée. Une institution prudente doit donc construire la possibilité de corriger son propre jugement dans la mesure elle-même."],'qclaim':'Quelle thèse défend le point de vue A ?','aclaim':'Une restriction grave de liberté doit être périodiquement justifiée à nouveau, car durée, preuve et alternatives évoluent.','qinfer':'Pourquoi la durée change-t-elle l’analyse ?','ainfer':'Parce qu’une raison proportionnée à une mesure brève peut devenir insuffisante lorsque la restriction se prolonge.','qassume':'Que suppose un mécanisme de révision fiable ?','aassume':'Des critères annoncés permettant de comparer les nouvelles preuves, les risques et les alternatives.','qrelation':'Comment le texte répond-il au coût des réexamens ?','arelation':'Il propose une révision standardisée plutôt qu’une répétition entièrement nouvelle de la décision.','astance':'Privilégier la réversibilité et la justification continue lorsque la liberté est fortement restreinte.','asummary':'Une mesure restrictive n’hérite pas indéfiniment de sa justification initiale; elle doit rester proportionnée aux faits actuels.'},
 {'id':'fr-c1-u06-p04','seq':34,'title':'Point de vue B : l’usage de la force doit être jugé dans une séquence complète','genre':'argument','domains':['public','educational'],'topics':['enforcement','proportionality','register'],'pair':PAIR,'paras':["Le second point de vue examine un autre risque : juger une intervention uniquement à partir de son dernier geste. Dans un cas fictif, une personne est interceptée après plusieurs avertissements contradictoires, puis une force physique est utilisée. Le commentaire soutient que la proportionnalité ne peut être évaluée sans reconstruire ce que chaque participant pouvait raisonnablement comprendre à chaque étape.","Le texte distingue autorité, nécessité et intensité. Une personne chargée d’appliquer une règle peut avoir une autorité générale sans que chaque forme de contrainte soit nécessaire. Inversement, l’absence d’un résultat grave ne prouve pas que la méthode choisie était proportionnée.","Le meilleur contreargument avertit qu’une reconstruction trop détaillée peut excuser après coup n’importe quelle escalade. Le point de vue B répond en fixant des questions indépendantes du résultat : quelles alternatives existaient, quel risque était observable, quelle information a été communiquée et à quel moment la force a-t-elle augmenté ? Ces questions permettent de critiquer l’intervention sans supposer que tout usage de force est identique.","La conclusion insiste aussi sur le langage. Des mots familiers ou chargés peuvent révéler l’attitude d’un témoin, mais l’analyse institutionnelle reformule les actions avec des termes descriptifs avant de juger leur justification. Le registre devient une donnée sur le récit, pas un raccourci vers la conclusion."],'qclaim':'Quelle méthode le point de vue B propose-t-il pour juger une intervention ?','aclaim':'Reconstruire la séquence, l’information disponible, les alternatives et l’intensité de la contrainte avant d’évaluer sa proportionnalité.','qinfer':'Pourquoi l’absence de blessure grave n’est-elle pas décisive ?','ainfer':'Parce qu’une méthode peut être disproportionnée même si le dommage final reste limité.','qassume':'Que suppose une critique qui évite l’excuse rétrospective ?','aassume':'Des critères indépendants du résultat, comme le risque observable et les alternatives disponibles au moment de la décision.','qrelation':'Comment le texte traite-t-il le risque d’excuser toute escalade par le contexte ?','arelation':'Il reconstruit le contexte mais impose des questions stables sur nécessité, information et alternatives.','astance':'Évaluer la force par une séquence factuelle et des critères de proportionnalité plutôt que par le seul résultat ou le ton du récit.','asummary':'La justification d’une intervention dépend de ce qui était nécessaire et observable à chaque étape, pas seulement de son issue.','across':'Les deux textes exigent une justification révisable et proportionnée; A met l’accent sur la durée d’une restriction de liberté, B sur l’escalade et les alternatives pendant une intervention.'},
 {'id':'fr-c1-u06-p05','seq':35,'title':'Interpréter une exception sans laisser l’exception avaler la règle','genre':'commentary','domains':['public','professional'],'topics':['exceptions','documents','review'],'paras':["Le dernier dossier porte sur une règle fictive qui permet une mesure exceptionnelle lorsque certaines conditions urgentes sont réunies. Le désaccord ne concerne pas seulement la présence d’un danger; il porte sur la manière de lire les mots qui limitent l’exception et sur le moment où la situation revient dans le régime ordinaire.","L’analyse commence par identifier la fonction de l’exception. Une mesure temporaire peut être conçue pour permettre une réponse rapide lorsque la procédure normale serait trop lente. Cette fonction ne signifie pas que les garanties ordinaires disparaissent toutes : certaines peuvent être reportées, d’autres doivent continuer à s’appliquer précisément parce que le contrôle immédiat est plus faible.","Le contreargument soutient qu’une lecture trop restrictive rendrait l’exception inutilisable dans une vraie urgence. Le dossier répond en distinguant vitesse et absence de contrôle. Une décision peut être rapide tout en laissant une trace écrite, une durée maximale et une révision par une autre personne ou instance dès que cela devient possible.","La recommandation finale associe chaque pouvoir exceptionnel à une condition de sortie. L’institution doit savoir non seulement ce qui déclenche la mesure, mais aussi ce qui oblige à y mettre fin. Une exception dont les critères de sortie sont indéfinis risque de transformer progressivement le provisoire en règle générale."],'qclaim':'Quel problème interprétatif pose une mesure exceptionnelle ?','aclaim':'Il faut expliquer à la fois ce qui déclenche l’exception, quelles garanties subsistent et ce qui oblige à revenir au régime ordinaire.','qinfer':'Pourquoi une procédure rapide peut-elle rester contrôlable ?','ainfer':'Parce qu’elle peut conserver une trace, une durée limitée et une révision ultérieure même si certaines étapes sont différées.','qassume':'Que suppose une condition de sortie efficace ?','aassume':'Des faits observables permettant de déterminer que les raisons exceptionnelles ne sont plus présentes.','qrelation':'Comment le texte répond-il à l’objection qu’une lecture stricte neutralise l’urgence ?','arelation':'Il distingue la rapidité nécessaire de l’absence totale de contrôle et maintient des garanties adaptées au temps disponible.','astance':'Lire les pouvoirs exceptionnels avec des déclencheurs et des conditions de sortie explicites.','asummary':'Une exception interprétée de façon responsable reste limitée par sa fonction, sa durée, ses traces et une voie de retour au régime ordinaire.'}
 ]
def checkpoint(groups,deck,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]]
 paras=["Ce checkpoint réunit plusieurs difficultés de l’unité dans un seul dossier fictif. Une institution reçoit une information urgente, adopte une mesure provisoire, puis découvre que certains faits sont moins clairs qu’ils ne paraissaient au départ. Le lecteur doit distinguer la règle, la preuve, la qualification, la conséquence et la possibilité de corriger la décision.","La première étape consiste à reconstruire la chronologie sans utiliser les conclusions comme prémisses. Un récit peut parler d’un suspect, d’une faute ou d’un danger avant que ces catégories soient établies. Le dossier remplace chaque étiquette par les observations qui la soutiennent et indique ce qui reste contesté.","La deuxième étape compare deux erreurs possibles : agir trop tard face à un risque réel ou maintenir trop longtemps une restriction devenue inutile. Une bonne décision ne supprime pas ce conflit; elle rend visibles le seuil choisi, la gravité des conséquences et la manière dont de nouvelles informations pourraient changer le résultat.","La synthèse revient enfin à l’interprétation. Une règle n’est pas seulement une phrase isolée : elle possède une portée, une fonction, des conditions et souvent une relation avec d’autres garanties. L’analyse la plus forte indique le résultat retenu, le meilleur argument contraire et la condition précise qui imposerait une révision."]
 paras[1]+=' Révision cumulative : '+'; '.join(f'« {f} »' for f in forms)+'.';paras,text=fit(paras,lo,hi);P=base.prior(prior);rev=[base.rev(f,P) for f in forms];ids={t['form']:t['id'] for t in rev}
